	$interaction_type = 'spell_cast'
	interaction_slave['repulse'] = -100
	$special_part = {
		sparks -= 2
		if master_mage = 0:
			$text[1] = $fail_spell[interaction]
		else
			$play_sound[1] = 'auspex'
			auspex = 1
		end
		if (master_mage - boost_up['master_mage']) = 0: master_mage_rate += (skill_adv_mul * 1)
	}
end

